from pathlib import Path
import os, tempfile
p = Path('main.go')
content = '''package main

import (
	\"crypto/rand\"
	\"math/big\"
	\"os\"
	\"text/template\"
)

func main() {
	n, err := rand.Int(rand.Reader, big.NewInt(100))
	if err "'!= nil {
		panic(err)
	}

	tmpl, err := template.New("greeting").Parse("Hello World {{.}}'"\\\\n\")
	if err "'!= nil {
		panic(err)
	}
	if err := tmpl.Execute(os.Stdout, n); err != nil {
		panic(err)
	}
}
'"'''
fd, tmp = tempfile.mkstemp(dir=p.parent, prefix='.main.go.')
try:
    with os.fdopen(fd, 'w') as f:
        f.write(content)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, p)
finally:
    if os.path.exists(tmp):
        os.unlink(tmp)
